<script setup>
import ConfirmDialog from './ui/ConfirmDialog.vue'
import HolidayEditor from './HolidayEditor.vue'
import AdminPolicyEditor from './AdminPolicyEditor.vue'
import { ref,onMounted,computed,watch } from 'vue'
import { useRoute } from 'vue-router'
import { api } from '../api'
import { useWorkflowWrite } from '../composables/useWorkflowWrite'
import PageHeader from './ui/PageHeader.vue'
const route=useRoute(),tab=computed(()=>route.params.tab||'overview'),data=ref(null),error=ref(''),notice=ref(''),offset=ref(0),reason=ref(''),site=ref(null),announcement=ref({title:'',content:'',published:false,reason:''}),editing=ref(null),writes=useWorkflowWrite('admin')
const statusChoice=ref(null)
async function confirmStatus(){const user=statusChoice.value;if(!user)return;await act(()=>writes.send('/admin/users/'+user.id+'/status',{status:user.status==='active'?'disabled':'active',reason:reason.value,expected_version:user.version}));if(!error.value)statusChoice.value=null}
const filters=ref({q:'',role:'',status:''});let serial=0
const titles={overview:'管理概览',users:'用户账号',announcements:'公告',site:'站点设置',audit:'操作记录'}
async function load(){const token=++serial;try{const query=new URLSearchParams({offset:offset.value,...Object.fromEntries(Object.entries(filters.value).filter(([,v])=>v))});const result=await api.flow('/admin/'+tab.value+'?'+query);if(token!==serial)return;data.value=result;if(tab.value==='site'){const {version,...payload}=data.value;site.value=payload}}catch(e){error.value=e.message}}
async function act(fn){if(writes.busy.value)return;try{await fn();await load();error.value='';notice.value='更改已保存。'}catch(e){error.value=e.message}}
async function saveSite(){await act(()=>writes.send('/admin/site',{...site.value,reason:reason.value,expected_version:data.value.version},'PUT'))}
async function saveNotice(){await act(async()=>{await writes.send('/admin/announcements'+(editing.value?'/'+editing.value.id:''),{...announcement.value,expected_version:editing.value?.version||0},editing.value?'PUT':'POST');editing.value=null;announcement.value={title:'',content:'',published:false,reason:''}})}
watch(tab,()=>{offset.value=0;data.value=null;load()});onMounted(load)
</script>
<template><div class="reading-page"><PageHeader :title="titles[tab]||'管理'" description="仅账号与站点管理，不提供代读日记或模型密钥。"/><RouterLink class="btn" to="/admin/feedback">私密反馈</RouterLink><RouterLink class="btn" to="/admin/security">管理账号安全</RouterLink><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
<section v-if="data&&tab==='overview'" class="card"><p>账号 {{ data.users }} · 可用 {{ data.active }}</p><p v-if="data.timezone">统计时区：{{ data.timezone }}</p><p v-for="(group,key) in data.groups" :key="key">{{ key==='ordinary'?'普通账号':'管理账号' }}：共 {{ group.total }} · 可用 {{ group.active }} · 停用 {{ group.disabled }} · 今日新增 {{ group.created_today }} · 近7日登录 {{ group.logged_in_7_days }}</p><p>已发布公告 {{ data.published_announcements }}</p><p>{{ data.site.site_name }} · 注册策略 {{ {open:'直接注册',invite:'邀请兼容',closed:'已关闭'}[data.site.registration] }}</p><RouterLink to="/admin/site">查看站点策略</RouterLink></section>
<section v-if="data&&tab==='users'" class="card"><form @submit.prevent="offset=0;load()"><label>搜索用户名<input v-model="filters.q" maxlength="50"/></label><label>角色<select v-model="filters.role"><option value="">全部角色</option><option value="user">普通账号</option><option value="owner">管理账号</option></select></label><label>状态<select v-model="filters.status"><option value="">全部状态</option><option value="active">可用</option><option value="disabled">已停用</option></select></label><button class="btn">查询</button></form><p>匹配 {{ data.total??data.items.length }} 个账号</p><label>操作原因<input v-model="reason" maxlength="2000"/></label><article v-for="user in data.items" :key="user.id"><h2>{{ user.username }}</h2><p>#{{ user.id }} · {{ user.role==='owner'?'管理账号':'普通账号' }} · {{ user.status==='active'?'可用':'已停用' }} · v{{ user.version }} · {{ user.email_verified?'已验证邮箱':'无验证邮箱' }}</p><p>最近登录：{{ user.last_login_at||'暂无可用历史' }}</p><button class="btn" :disabled="writes.busy.value||!reason.trim()" @click="statusChoice=user">{{ user.status==='active'?'停用账号并撤销会话':'恢复使用资格' }}</button></article></section>
<form v-if="site&&tab==='site'" class="card" @submit.prevent="saveSite"><label>站点名称<input v-model="site.site_name" maxlength="80" required/></label><label>说明<textarea v-model="site.description" maxlength="500"/></label><label>注册策略<select v-model="site.registration"><option value="open">直接注册（不需邀请码）</option><option value="invite">保留邀请兼容</option><option value="closed">关闭新注册</option></select></label><label><input type="checkbox" v-model="site.email_required"/>新注册须先验证邮箱（要求邮件已配置）</label><label>改密会话策略<select v-model="site.password_sessions"><option value="all">撤销全部会话，重新登录</option><option value="others">仅撤销其他会话</option></select></label><label>操作原因<input v-model="reason" required maxlength="2000"/></label><button class="btn primary" :disabled="writes.busy.value">保存站点设置</button></form>
<template v-if="data&&tab==='announcements'"><form class="card" @submit.prevent="saveNotice"><h2>{{ editing?'编辑公告':'新增公告' }}</h2><label>标题<input v-model="announcement.title" maxlength="120" required/></label><label>正文<textarea v-model="announcement.content" maxlength="4000" required/></label><label><input type="checkbox" v-model="announcement.published"/>站内发布</label><label>操作原因<input v-model="announcement.reason" required/></label><details><summary>预览公告（尚未发布）</summary><h3>{{ announcement.title }}</h3><p class="original-text">{{ announcement.content }}</p></details><button class="btn" :disabled="writes.busy.value">保存公告</button></form><article class="card" v-for="row in data.items" :key="row.id"><h2>{{ row.title }}</h2><p class="original-text">{{ row.content }}</p><p>{{ row.published?'已发布':'草稿' }} · v{{ row.version }}</p><button class="btn" @click="editing=row;announcement={title:row.title,content:row.content,published:row.published,reason:''}">编辑 / 撤下</button></article></template>
<section v-if="data&&tab==='audit'" class="card"><article v-for="row in data.items" :key="row.id"><p>{{ row.created_at }} · 管理人 #{{ row.actor_id }}</p><p>{{ row.action }} · {{ row.target }} · v{{ row.version }}</p><p>{{ row.reason }}</p></article></section>
<AdminPolicyEditor v-if="tab==='site'"/><HolidayEditor v-if="tab==='site'"/><div v-if="['users','announcements','audit'].includes(tab)" class="action-group"><button class="btn" :disabled="offset===0" @click="offset=Math.max(0,offset-50);load()">上一页</button><button class="btn" :disabled="!data?.items?.length" @click="offset+=50;load()">下一页</button></div><ConfirmDialog :open="!!statusChoice" :title="statusChoice?.status==='active'?'停用账号并撤销会话':'恢复账号使用资格'" confirm-label="确认更改账号状态" :busy="writes.busy.value" @cancel="statusChoice=null" @confirm="confirmStatus"><p>{{ statusChoice?.username }}</p><p>操作原因：{{ reason }}</p><p v-if="error" class="error">{{ error }}</p></ConfirmDialog></div></template>
